import numpy as np
def transform(grid):
    g=np.array(grid); H,W=g.shape
    # bar: vertical stripe of colors, found as columns with a repeated color
    cols={}
    for c in range(W):
        col=g[:,c]; nz=col[col!=0]
        if len(nz)>=2 and len(set(nz))==1 and len(nz)==col.max() and len(nz)== (col!=0).sum():
            cols[c]=col[0]
    # simpler: bar columns = cols where nonzero run of same color length>=2 contiguous
    barcols=[]
    for c in range(W):
        col=g[:,c]; nz=col!=0
        idx=np.where(nz)[0]
        if len(idx)>=2 and len(set(col[idx]))==1 and np.all(np.diff(idx)==1):
            barcols.append(c)
    barcols.sort()
    # contiguous group of barcols
    groups=[]; cur=[barcols[0]]
    for c in barcols[1:]:
        if c==cur[-1]+1: cur.append(c)
        else: groups.append(cur); cur=[c]
    groups.append(cur)
    bar=[g[0,c] for c in groups[0]]
    colors=[x for x in bar if x!=0]
    # shape cells: remaining nonzero cells
    mask=g!=0
    for c in groups[0]:
        mask[:,c]=False
    rows=np.where(mask.any(1))[0]; ccols=np.where(mask.any(0))[0]
    shape=g[np.ix_(rows,ccols)]
    sc=np.unique(shape[shape!=0])[0]
    h=len(rows)
    pos=colors.index(sc)
    out=np.zeros_like(g)
    for i,col in enumerate(colors):
        off=(i-pos)*h
        for r in range(h):
            for cc in range(shape.shape[1]):
                if shape[r,cc]:
                    out[rows[0]+off+r, ccols[0]+cc]=col
    return out.tolist()

