import numpy as np
def transform(grid):
    g=np.array(grid); H,W=g.shape
    # bar columns: per column first vertical run >=2 of one color
    cand={}
    for c in range(W):
        col=g[:,c]; r=0
        while r<H:
            if col[r]!=0:
                rr=r
                while rr+1<H and col[rr+1]==col[r]: rr+=1
                if rr>r and c not in cand: cand[c]=(int(col[r]), r, rr-r+1)
                r=rr+1
            else: r+=1
    barcols=sorted(cand)
    groups=[]; cur=[barcols[0]]
    for c in barcols[1:]:
        if c==cur[-1]+1 and cand[c][1:]==cand[cur[-1]][1:]: cur.append(c)
        else: groups.append(cur); cur=[c]
    groups.append(cur)
    bg=groups[0]
    colors=[cand[c][0] for c in bg]
    rest=g.copy()
    for c in bg: rest[:,c]=0
    # components per color in rest
    from scipy import ndimage
    comps=[]
    for col in colors:
        m=(rest==col)
        lab,n=ndimage.label(m, structure=np.ones((3,3)))
        for k in range(1,n+1):
            ys,xs=np.where(lab==k)
            comps.append((col, ys.min(), ys.max(), xs.min(), xs.max()))
    # template: take largest component; assume identical shapes
    col0, y0a, y0b, x0a, x0b = comps[0]
    h=y0b-y0a+1
    tpl=(rest[y0a:y0b+1, x0a:x0b+1]==col0).astype(int)
    pos0=colors.index(col0)
    out=g.copy()
    present={c[0] for c in comps}
    for i,col in enumerate(colors):
        if col in present: continue
        off=(i-pos0)*h
        sub=out[y0a+off:y0a+off+h, x0a:x0b+1]
        for r in range(h):
            for cc in range(tpl.shape[1]):
                if tpl[r,cc]: sub[r,cc]=col
    return out.tolist()

